func uniqueAddress(email string) string {
    parts := strings.Split(email, "@")
    local, domain := parts[0], parts[1]

    local = strings.ReplaceAll(local, ".", "")

    plusIndex := strings.Index(local, "+")
    if plusIndex >= 0 {
        local = local[:plusIndex]
    }

    return local + "@" + domain
}

