    l, r := 0, len(nums)-1
    i := -1
    for l <= r {
        m := (l + r) / 2
        if nums[m] < target {
            l = m + 1
        } else if nums[m] > target {
            r = m - 1
        } else {
            i = m
            if leftBias {
