func pairSum(head *ListNode) int {
    // find mid of a list
    slow := head
    fast := head.Next
    for fast != nil && fast.Next != nil {
        slow = slow.Next
        fast = fast.Next.Next
    }

    // reverse links in 2nd half
    second := reverse(slow.Next)
    // split into 2 lists
    slow.Next = nil

    // traverse two lists with pointers and compare twin sum
    first := head
    var maxSum int
    for first != nil && second != nil {
