func robUtil(nums []int, st, end int) int {
    dp := make([]int, len(nums))
    dp[st] = nums[st]
    dp[st+1] = max(nums[st], nums[st+1])

    for i := st+2; i < end; i++ {
        dp[i] = max(nums[i]+dp[i-2], dp[i-1])
    }

    return dp[end-1]
}

