func findSum(nums []int, idx int, target int, memo map[string]int) int {
    key := fmt.Sprint(idx)+"*"+fmt.Sprint(target)

    if val, ok := memo[key]; ok {
        return val
    }

    if idx == len(nums) {
        if target == 0 {
            return 1
        }

        return 0
